script:
const BADRIA_SETTLEMENT_TYPE_DEPARTMENT_MAP = {
    "Production": "Production - BS",
    "Sales": "SALES MAN - BS",
};

frappe.ui.form.on("Full and Final Statement", {
    onload(frm) {
        badria_filter_employee_by_settlement_type(frm);
    },
    custom_settlement_type(frm) {
        badria_filter_employee_by_settlement_type(frm);
        badria_clear_employee_on_department_mismatch(frm);
    },
});

function badria_filter_employee_by_settlement_type(frm) {
    frm.set_query("employee", () => {
        const department = BADRIA_SETTLEMENT_TYPE_DEPARTMENT_MAP[frm.doc.custom_settlement_type];
        if (department) {
            return { filters: { department } };
        }
        return {};
    });
}

function badria_clear_employee_on_department_mismatch(frm) {
    // Department is fetched read-only from the selected Employee, so it always
    // reflects that Employee's real department. If it no longer matches the
    // newly chosen Settlement Type, the Employee is stale - clear it instead
    // of silently leaving a cross-department Employee on the form.
    const department = BADRIA_SETTLEMENT_TYPE_DEPARTMENT_MAP[frm.doc.custom_settlement_type];
    if (frm.doc.employee && department && frm.doc.department && frm.doc.department !== department) {
        frm.set_value("employee", "");
    }
}

const BADRIA_SHIFT_EMPLOYEE_DEPARTMENT = "Production - BS";

frappe.ui.form.on("Stock Entry", {
    onload(frm) {
        // Only auto-fill on a brand-new entry. A saved draft or a
        // submitted document already has its real Shift Employees on
        // file - re-fetching live shift data on every load would silently
        // overwrite/append to that and mark the form dirty for no reason.
        if (frm.is_new()) {
            badria_load_shift_employees(frm);
        }
        badria_filter_shift_employee_by_department(frm);
    },
    custom_shift_type(frm) {
        badria_load_shift_employees(frm);
    },
    posting_date(frm) {
        badria_load_shift_employees(frm);
    },
    custom_department(frm) {
        badria_filter_shift_employee_by_department(frm);
        badria_load_shift_employees(frm);
    },
});

function badria_load_shift_employees(frm) {
    frm.clear_table("custom_shift_employees");
    if (!frm.doc.custom_shift_type || !frm.doc.posting_date) {
        frm.refresh_field("custom_shift_employees");
        return;
    }
    frappe.call({
        method: "badria_pwa.manufacturing.stock_entry.get_shift_employees",
        args: {
            shift_type: frm.doc.custom_shift_type,
            posting_date: frm.doc.posting_date,
            // Shift Employees is a production-shift table - always restricted
            // to Production - BS, regardless of the Department field's value.
            department: BADRIA_SHIFT_EMPLOYEE_DEPARTMENT,
        },
        callback(r) {
            (r.message || []).forEach((row) => {
                const child = frm.add_child("custom_shift_employees");
                child.employee = row.employee;
                child.employee_name = row.employee_name;
            });
            frm.refresh_field("custom_shift_employees");
        },
    });
}

function badria_filter_shift_employee_by_department(frm) {
    // Also restricts employees added manually to the child table to the
    // same fixed department as the auto-fetched list.
    frm.set_query("employee", "custom_shift_employees", () => {
        return { filters: { department: BADRIA_SHIFT_EMPLOYEE_DEPARTMENT } };
    });
}

frappe.ui.form.on("Employee Attendance Tool", {
    refresh(frm) {
        badria_ensure_production_summary_section(frm);
    },
    set_primary_action(frm) {
        frm.page.set_secondary_action(__("Add Production"), () => {
            badria_open_add_production_dialog(frm);
        });
    },
    date(frm) {
        badria_render_production_summary(frm, []);
    },
    load_employees(frm) {
        badria_load_production_summary(frm);
        badria_filter_employees_by_shift(frm);
    },
});

function badria_filter_employees_by_shift(frm) {
    if (!frm.doc.shift || !frm.doc.date) return;

    frappe.call({
        method: "badria_pwa.api.employee_attendance_tool.get_shift_employees_for_date",
        args: { shift: frm.doc.shift, date: frm.doc.date },
    }).then((r) => {
        const shift_employees = new Set(r.message || []);

        ["unmarked_employees_multicheck", "half_marked_employees_multicheck"].forEach((fieldname) => {
            const field = frm.fields_dict[fieldname];
            if (!field || !field.$wrapper) return;

            field.$wrapper.find(".unit-checkbox").each(function () {
                const employee = $(this).find('input[type="checkbox"]').attr("data-unit");
                if (!shift_employees.has(employee)) {
                    // Removed (not just hidden) so "Select All" can't re-include
                    // an employee who isn't on the selected shift.
                    $(this).remove();
                }
            });
        });
    });
}

function badria_get_selected_employees(frm) {
    const full_day = frm.get_field("unmarked_employees_multicheck")?.get_checked_options() || [];
    const half_day = frm.get_field("half_marked_employees_multicheck")?.get_checked_options() || [];
    return [...new Set([...full_day, ...half_day])];
}

function badria_open_add_production_dialog(frm) {
    const employees = badria_get_selected_employees(frm);

    if (!employees.length) {
        frappe.throw({
            message: __("Please select the employees you want to add production for."),
            title: __("Mandatory"),
        });
    }
    if (!frm.doc.date) {
        frappe.throw({
            message: __("Please set the Attendance Date first."),
            title: __("Mandatory"),
        });
    }

    frappe.db
        .get_list("Employee", {
            filters: { name: ["in", employees] },
            fields: ["name", "employee_name"],
            limit_page_length: 0,
        })
        .then((employee_records) => {
            const employee_name_map = {};
            employee_records.forEach((emp) => (employee_name_map[emp.name] = emp.employee_name));
            badria_render_add_production_dialog(frm, employees, employee_name_map);
        });
}

function badria_render_add_production_dialog(frm, employees, employee_name_map) {
    const dialog = new frappe.ui.Dialog({
        title: __("Add Production"),
        size: "large",
        fields: [
            {
                fieldname: "production_date",
                fieldtype: "Date",
                label: __("Production Date"),
                default: frm.doc.date,
                read_only: 1,
            },
            {
                fieldname: "default_quantity",
                fieldtype: "Float",
                label: __("Quantity (applies to all employees)"),
                description: __("Set once to fill every employee row below. You can still edit any single row afterwards if that employee actually produced a different quantity."),
                onchange() {
                    badria_apply_default_quantity(dialog);
                },
            },
            {
                fieldname: "production_rows_html",
                fieldtype: "HTML",
            },
        ],
        primary_action_label: __("Add Production"),
        primary_action() {
            badria_submit_production_entries(frm, dialog);
        },
    });

    const $wrapper = dialog.get_field("production_rows_html").$wrapper;
    const $table = $(`
        <table class="table table-bordered">
            <thead>
                <tr>
                    <th style="width: 60%">${__("Employee")}</th>
                    <th style="width: 40%">${__("Quantity")}</th>
                </tr>
            </thead>
            <tbody></tbody>
        </table>
    `);
    $table.appendTo($wrapper);
    const $tbody = $table.find("tbody");

    dialog.production_rows = employees.map((employee) => {
        const $row = $("<tr>").appendTo($tbody);
        $("<td>")
            .text(`${employee} : ${employee_name_map[employee] || ""}`)
            .appendTo($row);

        const $qty_cell = $("<td>").appendTo($row);

        const qty_field = frappe.ui.form.make_control({
            parent: $qty_cell,
            df: { fieldname: "quantity", fieldtype: "Float", placeholder: __("Quantity") },
            render_input: true,
        });

        return { employee, qty_field };
    });

    dialog.show();
}

function badria_apply_default_quantity(dialog) {
    const default_quantity = dialog.get_value("default_quantity");
    if (!default_quantity) return;

    dialog.production_rows.forEach((row) => {
        row.qty_field.set_value(default_quantity);
    });
}

function badria_submit_production_entries(frm, dialog) {
    const entries = [];

    for (const row of dialog.production_rows) {
        const quantity = flt(row.qty_field.get_value());

        if (quantity <= 0) {
            frappe.throw({
                message: __("Please enter a Quantity greater than 0 for {0}.", [row.employee]),
                title: __("Mandatory"),
            });
        }
        entries.push({ employee: row.employee, quantity });
    }

    frappe.call({
        method: "badria_pwa.api.production_entry.create_from_attendance_tool",
        args: { date: frm.doc.date, entries },
        freeze: true,
        freeze_message: __("Creating Production Entries..."),
    }).then((r) => {
        const result = r.message || {};
        const created_count = (result.created || []).length;

        if (created_count) {
            frappe.show_alert({
                message: __("{0} Production Entry(s) created successfully.", [created_count]),
                indicator: "green",
            });
        }
        if (result.errors && result.errors.length) {
            frappe.msgprint({
                title: __("Some Production Entries Could Not Be Created"),
                indicator: "red",
                message: result.errors.join("<br>"),
            });
        }
        dialog.hide();
        badria_load_production_summary(frm);
    });
}

function badria_ensure_production_summary_section(frm) {
    if (frm.badria_production_summary) return frm.badria_production_summary;

    const $wrapper = $(`
        <div class="row form-section badria-production-summary-section">
            <div class="section-head">${__("Production Added")}</div>
            <div class="section-body">
                <div class="badria-production-summary-empty text-muted">
                    ${__("No production entries recorded for this date yet.")}
                </div>
                <div class="badria-production-summary-table"></div>
            </div>
        </div>
    `).appendTo(frm.layout.wrapper);

    frm.badria_production_summary = {
        $wrapper,
        $empty: $wrapper.find(".badria-production-summary-empty"),
        $table: $wrapper.find(".badria-production-summary-table"),
        datatable: null,
    };
    return frm.badria_production_summary;
}

function badria_get_production_summary_columns() {
    return [
        {
            name: "employee",
            id: "employee",
            content: __("Employee"),
            width: 260,
        },
        {
            name: "production_entry",
            id: "production_entry",
            content: __("Production Entry"),
            width: 180,
            format: (value) => (value ? frappe.utils.get_form_link("Production Entry", value, true) : ""),
        },
        {
            name: "quantity",
            id: "quantity",
            content: __("Quantity"),
            width: 120,
        },
    ].map((column) => ({
        ...column,
        editable: false,
        sortable: false,
        focusable: false,
        dropdown: false,
        align: column.name === "quantity" ? "right" : "left",
    }));
}

function badria_render_production_summary(frm, rows) {
    const summary = badria_ensure_production_summary_section(frm);

    if (!rows.length) {
        summary.$empty.show();
        summary.$table.hide();
        return;
    }
    summary.$empty.hide();
    summary.$table.show();

    const columns = badria_get_production_summary_columns();
    const data = rows.map((row) => [
        `${row.employee} : ${row.employee_name || ""}`,
        row.name,
        row.production_quantity,
    ]);

    if (!summary.datatable) {
        summary.datatable = new frappe.DataTable(summary.$table.get(0), {
            columns,
            data,
            dynamicRowHeight: true,
            inlineFilters: true,
            layout: "fixed",
            cellHeight: 35,
            noDataMessage: __("No Data"),
            disableReorderColumn: true,
        });
    } else {
        summary.datatable.refresh(data, columns);
    }
}

function badria_load_production_summary(frm) {
    if (!frm.doc.date) return;

    frappe.call({
        method: "badria_pwa.api.production_entry.get_production_entries",
        args: { date: frm.doc.date },
    }).then((r) => {
        badria_render_production_summary(frm, r.message || []);
    });
}
